from pathlib import Path
import json,sys,math,torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'experiments'))
from r_capture_io_v1 import unpack,lexical_labels
torch.set_num_threads(6);torch.set_grad_enabled(False);host=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];data=unpack(torch.load(ROOT/'artifacts/r_wide_tokens_v1.pt',weights_only=True,mmap=True));meta=json.loads((ROOT/'artifacts/r_wide_tokens_v1_meta.json').read_text());classes=meta['classes'];ids=torch.tensor([c['id'] for c in classes]);lookup={int(t):i for i,t in enumerate(ids)};labels=lexical_labels(classes);ci=torch.tensor([lookup[int(t)] for t in data['token']]);X=data['0.gelu'].double();train=data['sequence']<384;valid=~train;Xi=X[train];c=ci[train];pos=data['position'].double();u=pos/64;positionlabels=torch.stack((u,u*u,torch.cos(pos*math.pi/2),torch.sin(pos*math.pi/2),torch.cos(pos*math.pi/8),torch.sin(pos*math.pi/8),torch.cos(pos*math.pi/32),torch.sin(pos*math.pi/32)),1);targets=torch.cat((labels[ci],positionlabels),1);means=torch.stack([Xi[c==i].mean(0) for i in range(len(ids))]);tm=torch.stack([targets[train][c==i].mean(0) for i in range(len(ids))]);within=Xi-means[c];tw=targets[train]-tm[c];Cwithin=within.T@within/len(within);crossTargets=within.T@tw/len(within)
calib=torch.load(ROOT/'artifacts/host_calib512_early.pt',weights_only=True,mmap=True);wr=torch.load(ROOT/'artifacts/n_host_calib0.pt',weights_only=True,mmap=True);ar=torch.load(ROOT/'artifacts/o_host_calib1.pt',weights_only=True,mmap=True);assert torch.equal(calib['inputs'],wr['inputs']) and torch.equal(calib['inputs'],ar['inputs']);ct=calib['inputs'].reshape(-1);W=calib['captures']['0.gelu'].reshape(-1,3072).double();negative=~torch.isin(ct,ids);construction=(torch.arange(len(W))<384*64)&negative;wordvalidation=(torch.arange(len(W))>=384*64)&negative;mu=W[construction].mean(0);center=W[construction]-mu;Cword=center.T@center/len(center);del center
P=host['transformer.h.0.mlp.c_proj.weight'].double();pb=host['transformer.h.0.mlp.c_proj.bias'].double();Z=data['0.raw'].double()+X@P.T+pb;wordpost=wr['captures']['0.raw'].reshape(-1,768).double()+W@P.T+pb;attention=ar['captures']['1.raw'].reshape(-1,768).double()-wordpost;amean=attention[:384*64].mean(0);zm=torch.stack([Z[train][c==i].mean(0) for i in range(len(ids))])+amean;zw=Z[train]+amean-zm[c];crossNative=within.T@zw/len(within);del within,zw,tw;A=means-mu;reports=[];candidates=[]
for mass in (.001,.01,.1,1.,10.):
 C=Cwithin+mass*Cword;C.diagonal().add_(float(C.trace()/3072)*1e-5);chol=torch.linalg.cholesky(C);inv=torch.cholesky_solve(A.T,chol);gram=A@inv;J=inv@torch.linalg.inv(gram);initial=torch.cholesky_solve(torch.cat((crossTargets,crossNative),1),chol);Ly=initial[:,:29];B=initial[:,29:];coeff=Ly+J@(tm-A@Ly);intercept=-mu@coeff;H=-B+J@(A@B-zm);pred=X[valid]@coeff+intercept;err=(pred[:,:21]>.5)!=(targets[valid,:21]>.5);diff=pred[:,21:]-targets[valid,21:];words=W[wordvalidation]@coeff+intercept;r={'word_mass':mass,'class_mean_constraint_error':float((A@coeff-tm).abs().max()),'native_class_mean_constraint_error':float((zm+A@H).abs().max()),'validation_tokens':int(valid.sum()),'all_lexical_fields_correct':int((~err.any(1)).sum()),'lexical_label_rms_error':float((pred[:,:21]-targets[valid,:21]).square().mean().sqrt()),'lexical_max_error':float((pred[:,:21]-targets[valid,:21]).abs().max()),'position_token_error_max':float((64*diff[:,0]).abs().max()),'position_token_error_rms':float((64*diff[:,0]).square().mean().sqrt()),'position_token_errors_above_quarter':int((64*diff[:,0].abs()>.25).sum()),'position_token_errors_above_half':int((64*diff[:,0].abs()>.5).sum()),'position_code_rms_by_field':diff.square().mean(0).sqrt().tolist(),'word_lexical_label_rms':float(words[:,:21].square().mean().sqrt()),'word_position_code_rms':float(words[:,21:].square().mean().sqrt()),'coefficient_max_abs':float(coeff.abs().max())};reports.append(r);candidates.append({'coefficients':coeff,'bias':intercept,'conditional_native_coefficients':H,'report':r});print(json.dumps(r),flush=True)
out={'classes':ids,'class_labels':labels,'word_mean_features':mu,'native_attention_mean':amean,'candidates':candidates,'reports':reports,'lexical_fields':[f'{place}_bit{b}' for place in ('hundreds','tens','units') for b in range(4)]+['length1','length2','length3','spaced_numeric','plus','spaced_plus','equals','spaced_equals','newline'],'position_fields':['u','u2','cos4','sin4','cos16','sin16','cos64','sin64'],'method':'class-constrained covariance solve: numerical within-class target residual plus ordinary-word update covariance; native target is postMLP0 activation plus mean attention1 output'};torch.save(out,ROOT/'artifacts/r_wide_maps_v1.pt');(ROOT/'artifacts/r_wide_maps_v1.json').write_text(json.dumps(reports,indent=2)+'\n')
